/**
 * build-pro192-da-fe1.mjs — sinh content/exams/PRO192-DA-FE1.mjs: 🏁 Dự án cuối khoá CT Library 1.0 — TRẮC NGHIỆM TỔNG 50 câu
 * kiểu FE (đề TỰ SOẠN, source 'SAMPLE'): câu VIẾT MỚI theo 9 chương của PRO192 (Ch1 6 · Ch2 6 · Ch3 5 · Ch4 7 · Ch5 6 · Ch6 6
 * · Ch7 4 · Ch8 6 · Ch9 4), phần lớn trên domain CT Library, mỗi câu có lời giải song ngữ (vì sao đúng + từng đáp án sai).
 * 37 câu có code: mã ở ~/Documents/FLM-nguon/_repo/PRO192/gen/de/da-fe1/java/Qnn.java, CHẠY THẬT bằng chay.mjs (javac --release 8,
 * JDK 21 + JDK 8 thật trong Docker) ⇒ out.json. Builder này ĐỌC out.json và ném lỗi nếu đáp án đúng của một câu code không
 * trùng output thật (hoặc câu "lỗi biên dịch" mà javac lại chạy được) — đáp án không bao giờ là đoán.
 *
 *   node scripts/build-pro192-da-fe1.mjs
 * Seed: node scripts/academy-seed-exam.mjs --file ./content/exams/PRO192-DA-FE1.mjs --apply
 */
import fs from 'node:fs';
import path from 'node:path';

const DE = '/Users/admin/Documents/FLM-nguon/_repo/PRO192/gen/de/da-fe1';
const OUT = path.resolve(import.meta.dirname, '../content/exams/PRO192-DA-FE1.mjs');
const RA = JSON.parse(fs.readFileSync(path.join(DE, 'out.json'), 'utf8'));
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ma = (q) => fs.readFileSync(path.join(DE, 'java', `${q}.java`), 'utf8').replace(/^\/\/ expect: compile-error\n/, '').trimEnd();
const CH = {
  1: ['Chapter 1 — OO thinking & Java basics', 'Chương 1 — Tư duy OO & Java cơ bản'],
  2: ['Chapter 2 — Classes & objects', 'Chương 2 — Lớp & đối tượng'],
  3: ['Chapter 3 — Encapsulation & packages', 'Chương 3 — Đóng gói & package'],
  4: ['Chapter 4 — Inheritance & polymorphism', 'Chương 4 — Kế thừa & đa hình'],
  5: ['Chapter 5 — Abstract classes & interfaces', 'Chương 5 — Lớp trừu tượng & interface'],
  6: ['Chapter 6 — Exceptions', 'Chương 6 — Xử lý ngoại lệ'],
  7: ['Chapter 7 — Arrays of objects', 'Chương 7 — Mảng đối tượng'],
  8: ['Chapter 8 — Java Collections', 'Chương 8 — Java Collections'],
  9: ['Chapter 9 — Streams & files', 'Chương 9 — Luồng & tệp'],
};
const CE = ['Compilation error', 'Lỗi biên dịch'];
const qs = [];
const ngan = (t) => (t.length > 64 ? t.slice(0, 61).trimEnd() + '…' : t);
const theoNoiDung = (g, o, lang) => g.replace(/\(([A-D])\)/g, (_, c) => { const k = 'ABCD'.indexOf(c); return `«${ngan(o[k][lang] ?? o[k][0])}»`; });
/** q({ ch, ma?: 'Qnn', en, vi, o: [[en, vi] x4], d: chỉ số đúng, gEn, gVi }) */
function q(x) {
  const code = x.ma ? `<pre><code class="language-java">${esc(ma(x.ma))}</code></pre>` : '';
  if (x.ma) {
    const r = RA[x.ma];
    if (!r) throw new Error(`${x.ma}: chưa chạy (out.json)`);
    const dung = x.o[x.d][0];
    if (r.loi ? dung !== CE[0] : dung !== r.ra) throw new Error(`${x.ma}: đáp án «${dung}» ≠ output thật «${r.ra}»`);
  }
  // đáp án đúng xoay vòng vị trí A/B/C/D (tất định) — các lựa chọn sai giữ thứ tự viết
  const viTri = (qs.length * 7 + 2) % 4;
  const sai = x.o.filter((_, k) => k !== x.d);
  const o = [...sai.slice(0, viTri), x.o[x.d], ...sai.slice(viTri)];
  qs.push({
    kind: 'MCQ', points: 0.2,
    prompt: `<p>${x.en}</p>${code}|||<p>${x.vi}</p>${code}`,
    options: o.map(([en, vi]) => ({ text: `${esc(en)}|||${esc(vi ?? en)}` })),   // hiện bằng HTML ⇒ thoát < > &
    correctIndexes: [viTri],
    // lời giải viết "(B)…" theo thứ tự lúc soạn; đề xáo đáp án ⇒ đổi chữ cái thành «nội dung đáp án»
    explanation: `${esc(theoNoiDung(x.gEn, x.o, 0))} 📚 ${CH[x.ch][0]}.|||${esc(theoNoiDung(x.gVi, x.o, 1))} 📚 ${CH[x.ch][1]}.`,
  });
}

/* ═════════ Chương 1 ═════════ */
q({ ch: 1, ma: 'Q01', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['true false true'], ['true true true'], ['false false true'], ['true false false']], d: 0,
  gEn: 'Two string literals with the same text are the SAME object from the string pool, so a == b is true. new String("CT") always builds a new object on the heap, so a == c compares two different references: false. equals() compares the characters: true. (B) would need c to come from the pool too. (C) forgets the pool. (D) confuses equals with ==. Rule for the exam and for real code: compare text with equals(), never with ==.',
  gVi: 'Hai literal chuỗi cùng nội dung là CÙNG một đối tượng trong string pool, nên a == b là true. new String("CT") luôn dựng đối tượng mới trên heap, nên a == c so hai tham chiếu khác nhau: false. equals() so từng ký tự: true. (B) đúng khi c cũng lấy từ pool. (C) quên pool. (D) nhầm equals với ==. Luật cho phòng thi và cho code thật: so chữ bằng equals(), không bao giờ bằng ==.' });
q({ ch: 1, ma: 'Q02', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['3 1 3.5'], ['3.5 1 3.5'], ['3 1 3.0'], ['4 1 3.5']], d: 0,
  gEn: 'int / int is integer division: 7 / 2 = 3 (the fraction is dropped, not rounded — so not 4). 7 % 2 = 1. In (double) copies / members the CAST binds first, so 7.0 / 2 = 3.5. (C) would be (double) (copies / members) — cast after the integer division.',
  gVi: 'int / int là chia nguyên: 7 / 2 = 3 (bỏ phần lẻ, không làm tròn — nên không phải 4). 7 % 2 = 1. Trong (double) copies / members phép ÉP KIỂU chạy trước, nên 7.0 / 2 = 3.5. (C) là kết quả của (double) (copies / members) — ép sau khi đã chia nguyên.' });
q({ ch: 1, en: 'Which of the following is NOT a feature of the Java language?', vi: 'Điều nào sau đây KHÔNG phải đặc điểm của ngôn ngữ Java?', o: [['A class can extend several classes at once (multiple inheritance of classes)', 'Một lớp kế thừa nhiều lớp cùng lúc (đa kế thừa lớp)'], ['Source code is compiled to bytecode that runs on any JVM', 'Mã nguồn biên dịch thành bytecode chạy trên mọi JVM'], ['Unused objects are freed by the garbage collector', 'Đối tượng không dùng nữa được bộ gom rác giải phóng'], ['Every variable has a declared type checked by the compiler', 'Mọi biến có kiểu khai báo, trình biên dịch kiểm kiểu']], d: 0,
  gEn: 'Java allows ONE superclass per class (class Book extends LibraryItem); "multiple inheritance" exists only for interfaces (implements A, B). (B) "write once, run anywhere" through bytecode + JVM, (C) automatic garbage collection and (D) static, strong typing are all core features.',
  gVi: 'Java chỉ cho MỘT lớp cha mỗi lớp (class Book extends LibraryItem); "đa kế thừa" chỉ có với interface (implements A, B). (B) "viết một lần, chạy mọi nơi" nhờ bytecode + JVM, (C) tự động gom rác, (D) kiểu tĩnh, chặt — đều là đặc điểm cốt lõi.' });
q({ ch: 1, ma: 'Q04', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['lib library'], ['LIB library'], ['lib lib'], ['LIB librarylib']], d: 0,
  gEn: 'String is immutable: s.toUpperCase() RETURNS a new string "LIB" that nobody keeps; s still points to "lib". StringBuilder is mutable: append changes the builder itself, so sb is "library". To keep the upper case you must write s = s.toUpperCase().',
  gVi: 'String là bất biến: s.toUpperCase() TRẢ VỀ chuỗi mới "LIB" mà không ai giữ; s vẫn trỏ "lib". StringBuilder thì thay đổi được: append sửa chính nó, nên sb là "library". Muốn giữ chữ hoa phải viết s = s.toUpperCase().' });
q({ ch: 1, ma: 'Q05', en: 'The Scanner reads the text "3", a line break, then "Clean Code". What is printed?', vi: 'Scanner đọc chữ "3", một dấu xuống dòng, rồi "Clean Code". Chương trình in ra gì?', o: [['3[]'], ['3[Clean Code]'], ['3[3]'], ['An InputMismatchException is thrown', 'Ném InputMismatchException']], d: 0,
  gEn: 'nextInt() reads only the digits "3" and leaves the line break in the buffer. The following nextLine() reads up to that line break and returns what is before it: the EMPTY string. That is the classic "skipped input" bug of menus. Fix: read every line with nextLine() and convert (Integer.parseInt), as in every CT Library lab.',
  gVi: 'nextInt() chỉ đọc chữ số "3" và để lại dấu xuống dòng trong bộ đệm. nextLine() ngay sau đó đọc tới dấu xuống dòng ấy và trả phần đứng trước: chuỗi RỖNG. Đó là lỗi "trôi lệnh nhập" kinh điển của menu. Cách sửa: đọc mọi dòng bằng nextLine() rồi đổi kiểu (Integer.parseInt), như mọi lab CT Library.' });
q({ ch: 1, ma: 'Q06', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['true false'], ['true true'], ['false false'], ['false true']], d: 0,
  gEn: 'Autoboxing uses Integer.valueOf, which returns CACHED objects for −128…127. 127 comes from the cache twice — the same object, so == is true. 128 is outside the cache: two different Integer objects, == is false. == on wrapper objects compares references; use equals() or compare the int values.',
  gVi: 'Tự đóng hộp dùng Integer.valueOf, hàm này trả đối tượng CÓ SẴN trong bộ nhớ đệm cho −128…127. 127 lấy hai lần từ bộ đệm — cùng một đối tượng, == là true. 128 nằm ngoài bộ đệm: hai đối tượng Integer khác nhau, == là false. == trên lớp bao so tham chiếu; hãy dùng equals() hoặc so giá trị int.' });

/* ═════════ Chương 2 ═════════ */
q({ ch: 2, ma: 'Q07', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['OOP'], ['Java'], ['null'], ['Compilation error', 'Lỗi biên dịch']], d: 0,
  gEn: 'Book b2 = b1 copies the REFERENCE, not the object: both variables on the stack point to the same Book on the heap. Changing the title through b2 is visible through b1. Getting a second, independent book needs new Book(...) (or a copy constructor).',
  gVi: 'Book b2 = b1 chép THAM CHIẾU, không chép đối tượng: hai biến trên stack cùng trỏ một Book trên heap. Đổi title qua b2 thì nhìn qua b1 cũng thấy. Muốn có cuốn thứ hai độc lập phải new Book(...) (hoặc constructor sao chép).' });
q({ ch: 2, ma: 'Q08', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['Old Changed'], ['New Changed'], ['Old Old'], ['New New']], d: 0,
  gEn: 'Java always passes BY VALUE; for an object the value is a copy of the reference. rename() points its own copy b at a new Book — the caller\'s b is untouched, so "Old". retitle() uses its copy to reach the SAME object and changes its field — the caller sees "Changed".',
  gVi: 'Java luôn truyền THEO GIÁ TRỊ; với đối tượng, giá trị là bản sao của tham chiếu. rename() cho bản sao b của nó trỏ sang Book mới — b của nơi gọi không đổi, nên "Old". retitle() dùng bản sao để tới CÙNG đối tượng và sửa trường — nơi gọi thấy "Changed".' });
q({ ch: 2, en: 'In <code>void borrow() { Book b = new Book("Java"); int days = 14; }</code>, where do <code>b</code>, <code>days</code> and the Book object live while borrow() runs?', vi: 'Trong <code>void borrow() { Book b = new Book("Java"); int days = 14; }</code>, khi borrow() đang chạy thì <code>b</code>, <code>days</code> và đối tượng Book nằm ở đâu?', o: [['b and days on the stack (in borrow\'s frame), the Book object on the heap', 'b và days trên stack (khung của borrow), đối tượng Book trên heap'], ['All three on the heap', 'Cả ba trên heap'], ['b on the heap, days and the Book object on the stack', 'b trên heap, days và đối tượng Book trên stack'], ['All three in the static area', 'Cả ba trong vùng static']], d: 0,
  gEn: 'Local variables — primitives AND references — live in the method\'s stack frame and disappear when the method returns. Objects created with new live on the heap; when no reference points to them any more, the garbage collector may reclaim them. The static area holds static fields, not locals.',
  gVi: 'Biến cục bộ — kiểu nguyên thuỷ LẪN tham chiếu — nằm trong khung stack của phương thức và biến mất khi phương thức trả về. Đối tượng tạo bằng new nằm trên heap; khi không còn tham chiếu nào trỏ tới, bộ gom rác có thể thu hồi. Vùng static giữ trường static, không giữ biến cục bộ.' });
q({ ch: 2, ma: 'Q10', en: 'What is the result of compiling and running this code?', vi: 'Biên dịch và chạy đoạn code này thì kết quả là gì?', o: [CE, ['null'], ['An empty line', 'Một dòng trống'], ['A NullPointerException at run time', 'NullPointerException lúc chạy']], d: 0,
  gEn: `The compiler adds a default constructor ONLY when a class declares no constructor at all. Member declares Member(String), so new Member() does not exist — javac: "${(RA.Q10.ra.replace(/^.*?error: /, ''))}". That is why every JavaBean model in CT Library writes its empty constructor explicitly.`,
  gVi: `Trình biên dịch chỉ tự thêm constructor mặc định khi lớp KHÔNG khai báo constructor nào. Member đã khai Member(String), nên new Member() không tồn tại — javac báo: "${(RA.Q10.ra.replace(/^.*?error: /, ''))}". Vì thế mọi model JavaBean của CT Library đều tự viết constructor rỗng.` });
q({ ch: 2, ma: 'Q11', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['1 3 3 3'], ['1 1 1 1'], ['3 3 3 3'], ['1 3 3 1']], d: 0,
  gEn: 'count is static: ONE variable shared by the class, not one per object. Each constructor call adds 1 and copies the current value into that object\'s own id: a gets 1, b 2, c 3. Item.count and a.count are the same variable (reading a static through an object compiles but is misleading): 3.',
  gVi: 'count là static: MỘT biến dùng chung của lớp, không phải mỗi đối tượng một biến. Mỗi lần gọi constructor cộng 1 rồi chép giá trị hiện tại vào id riêng của đối tượng đó: a được 1, b 2, c 3. Item.count và a.count là cùng một biến (đọc static qua đối tượng vẫn biên dịch được nhưng dễ hiểu nhầm): 3.' });
q({ ch: 2, ma: 'Q12', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['0'], ['5'], ['Compilation error', 'Lỗi biên dịch'], ['null']], d: 0,
  gEn: 'Inside setCopies, the parameter copies SHADOWS the field copies, so copies = copies assigns the parameter to itself. The field keeps its default value 0. The fix is this.copies = copies — "this." names the field of the current object.',
  gVi: 'Trong setCopies, tham số copies CHE trường copies, nên copies = copies gán tham số cho chính nó. Trường giữ giá trị mặc định 0. Sửa: this.copies = copies — "this." gọi tên trường của đối tượng hiện tại.' });

/* ═════════ Chương 3 ═════════ */
q({ ch: 3, en: 'A field is declared <code>protected</code> in class <code>LibraryItem</code> of package <code>model</code>. Which code can access it?', vi: 'Một trường khai <code>protected</code> trong lớp <code>LibraryItem</code> thuộc package <code>model</code>. Code nào truy cập được nó?', o: [['Classes of package model, plus subclasses of LibraryItem anywhere', 'Lớp trong package model, cộng lớp con của LibraryItem ở mọi nơi'], ['Only code inside LibraryItem itself, nothing else', 'Chỉ code bên trong chính LibraryItem, ngoài ra không ai'], ['Only classes of package model, never subclasses elsewhere', 'Chỉ lớp trong package model, lớp con ở nơi khác thì không'], ['Any class in any package, exactly like a public field', 'Mọi lớp ở mọi package, y như trường public']], d: 0,
  gEn: 'The four levels: private (the class only) < default/no modifier (same package) < protected (same package + subclasses anywhere) < public (everyone). (B) is private, (C) is the default level, (D) is public.',
  gVi: 'Bốn mức: private (chỉ lớp đó) < mặc định/không ghi (cùng package) < protected (cùng package + lớp con ở mọi nơi) < public (mọi lớp). (B) là private, (C) là mức mặc định, (D) là public.' });
q({ ch: 3, ma: 'Q14', en: 'What is the result of compiling and running this code?', vi: 'Biên dịch và chạy đoạn code này thì kết quả là gì?', o: [CE, ['2 then 1', 'In 2 rồi 1'], ['2 then 2', 'In 2 rồi 2'], ['An IllegalAccessError at run time', 'IllegalAccessError lúc chạy']], d: 0,
  gEn: `copies is private in Book, so Q14 may not read or write b.copies — javac stops: "${(RA.Q14.ra.replace(/^.*?error: /, ''))}". Nothing runs. Outside code must go through the methods Book chooses to offer (getCopies, and a setter that validates).`,
  gVi: `copies là private trong Book, nên Q14 không được đọc hay ghi b.copies — javac dừng: "${(RA.Q14.ra.replace(/^.*?error: /, ''))}". Không có gì chạy. Code bên ngoài phải đi qua các phương thức Book cho phép (getCopies, và setter có kiểm tra).` });
q({ ch: 3, en: 'Book keeps <code>copies</code> private and offers <code>setCopies(int copies)</code> that refuses negative numbers. What does this design achieve?', vi: 'Book để <code>copies</code> private và có <code>setCopies(int copies)</code> từ chối số âm. Thiết kế này đạt được gì?', o: [['No code outside Book can put the object into an invalid state', 'Không code nào bên ngoài Book đưa được đối tượng vào trạng thái sai'], ['The program runs faster because fields are private', 'Chương trình chạy nhanh hơn vì trường là private'], ['Book can no longer be extended', 'Book không còn kế thừa được nữa'], ['copies becomes a constant', 'copies trở thành hằng số']], d: 0,
  gEn: 'Encapsulation = hide the data, expose behaviour that keeps the rules. Every change of copies passes through ONE method that checks it, so "−3 copies" can never exist. Private does not change speed (B), does not forbid inheritance — that is final (C) — and a field with a setter is not a constant (D).',
  gVi: 'Đóng gói = giấu dữ liệu, mở hành vi giữ luật. Mọi thay đổi copies đi qua MỘT phương thức có kiểm tra, nên "−3 bản" không bao giờ tồn tại. private không đổi tốc độ (B), không cấm kế thừa — đó là final (C) — và trường có setter thì không phải hằng (D).' });
q({ ch: 3, en: 'In package <code>utils</code> there is <code>class CsvHelper { ... }</code> (no access modifier). Can <code>main.Main</code> (package <code>main</code>) write <code>new utils.CsvHelper()</code>?', vi: 'Trong package <code>utils</code> có <code>class CsvHelper { ... }</code> (không ghi mức truy cập). <code>main.Main</code> (package <code>main</code>) viết <code>new utils.CsvHelper()</code> được không?', o: [['No: a class without modifier is visible only inside its own package', 'Không: lớp không ghi mức truy cập chỉ thấy được trong package của nó'], ['Yes, after import utils.CsvHelper;', 'Được, sau khi import utils.CsvHelper;'], ['Yes, classes are public by default', 'Được, lớp mặc định là public'], ['Only if Main extends CsvHelper', 'Chỉ khi Main kế thừa CsvHelper']], d: 0,
  gEn: 'A top-level class has two choices: public, or package-private (no modifier). Package-private classes cannot even be named from another package, so the import itself fails to compile (B). There is no "public by default" in Java (C), and a subclass in another package still cannot see a package-private class (D).',
  gVi: 'Lớp cấp cao nhất chỉ có hai lựa chọn: public, hoặc mức package (không ghi). Lớp mức package không thể gọi tên từ package khác, nên chính dòng import đã lỗi biên dịch (B). Java không có "mặc định public" (C), và lớp con ở package khác vẫn không thấy lớp mức package (D).' });
q({ ch: 3, ma: 'Q17', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['0 7000 3000'], ['Compilation error', 'Lỗi biên dịch'], ['0 7000 1000'], ['A NullPointerException is thrown', 'Ném NullPointerException']], d: 0,
  gEn: 'int... fees is a varargs parameter: inside the method it IS an int[]. total() passes an empty array (not null), so the sum is 0; total(2000, 5000) builds {2000, 5000}; an existing int[] can be passed directly and is used as-is. All three calls compile.',
  gVi: 'int... fees là tham số varargs: bên trong phương thức nó CHÍNH LÀ int[]. total() truyền mảng rỗng (không phải null), tổng là 0; total(2000, 5000) dựng {2000, 5000}; một int[] có sẵn truyền thẳng vào và được dùng nguyên. Cả ba lời gọi đều biên dịch được.' });

/* ═════════ Chương 4 ═════════ */
q({ ch: 4, ma: 'Q18', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['DVD 3'], ['Item 14'], ['Item 3'], ['DVD 14']], d: 0,
  gEn: 'The declared type Item decides what you MAY call (javac checks Item has type() and loanDays()); the real object — a Dvd — decides WHICH body runs (dynamic dispatch at run time). Both methods are overridden in Dvd, so both answers come from Dvd. This is exactly how CT Library gets 14/7/3 loan days without a single if.',
  gVi: 'Kiểu khai báo Item quyết định được GỌI gì (javac kiểm Item có type() và loanDays()); đối tượng thật — một Dvd — quyết định thân NÀO chạy (điều phối động lúc chạy). Cả hai phương thức đều được Dvd ghi đè, nên cả hai câu trả lời đến từ Dvd. CT Library có 14/7/3 ngày mượn mà không cần một lệnh if nào chính là nhờ vậy.' });
q({ ch: 4, ma: 'Q19', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['AB'], ['BB'], ['AA'], ['BA']], d: 0,
  gEn: 'Methods are overridden and chosen by the OBJECT (B → "B"); fields are never overridden, only hidden, and are chosen by the DECLARED type (A → "A"). One more reason to keep fields private and reach them through methods.',
  gVi: 'Phương thức được ghi đè và chọn theo ĐỐI TƯỢNG (B → "B"); trường không bao giờ được ghi đè, chỉ bị che, và chọn theo KIỂU KHAI BÁO (A → "A"). Thêm một lý do để trường luôn private và truy cập qua phương thức.' });
q({ ch: 4, ma: 'Q20', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['Item Book Rare'], ['Rare Book Item'], ['Rare'], ['Book Rare']], d: 0,
  gEn: 'Every constructor first calls its parent\'s constructor — explicitly with super(...) or implicitly with super() — before running its own body. So the parent part is built first: Item, then Book, then RareBook prints "Rare". The object is built from the top of the hierarchy down.',
  gVi: 'Mọi constructor đều gọi constructor của lớp cha TRƯỚC — tường minh bằng super(...) hoặc ngầm bằng super() — rồi mới chạy thân của mình. Nên phần cha dựng trước: Item, rồi Book, rồi RareBook in "Rare". Đối tượng được dựng từ đỉnh cây kế thừa xuống.' });
q({ ch: 4, ma: 'Q21', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['long'], ['Integer'], ['Object'], ['Compilation error: ambiguous call', 'Lỗi biên dịch: lời gọi mơ hồ']], d: 0,
  gEn: 'Overload resolution happens at compile time in phases: first WITHOUT boxing (exact match, then widening), only then with boxing, then varargs. 5 is an int; widening int → long is found in the first phase, so f(long) wins before f(Integer) or f(Object) are even considered.',
  gVi: 'Chọn hàm nạp chồng diễn ra lúc biên dịch theo từng giai đoạn: trước hết KHÔNG đóng hộp (khớp đúng, rồi nới kiểu), chỉ sau đó mới đóng hộp, rồi tới varargs. 5 là int; nới int → long tìm được ngay giai đoạn đầu, nên f(long) thắng trước khi f(Integer) hay f(Object) được xét.' });
q({ ch: 4, ma: 'Q22', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['A'], ['B'], ['Compilation error', 'Lỗi biên dịch'], ['A NullPointerException is thrown', 'Ném NullPointerException']], d: 0,
  gEn: 'Static methods belong to the class and are not overridden — B.s() only HIDES A.s(). A call through a variable is resolved by the variable\'s declared type (A) at compile time, so A.s() runs. Polymorphism works only for instance methods.',
  gVi: 'Phương thức static thuộc về lớp và không được ghi đè — B.s() chỉ CHE A.s(). Lời gọi qua biến được xác định theo kiểu khai báo của biến (A) ngay lúc biên dịch, nên A.s() chạy. Đa hình chỉ áp dụng cho phương thức của đối tượng.' });
q({ ch: 4, en: '<code>class Book extends LibraryItem</code> overrides <code>toString()</code> and wants to reuse the parent\'s text, then add the ISBN. Which line is correct inside Book.toString()?', vi: '<code>class Book extends LibraryItem</code> ghi đè <code>toString()</code> và muốn dùng lại chuỗi của lớp cha rồi thêm ISBN. Dòng nào đúng trong Book.toString()?', o: [['return super.toString() + ", " + isbn;'], ['return toString() + ", " + isbn;'], ['return LibraryItem.toString() + ", " + isbn;'], ['return this.super.toString() + ", " + isbn;']], d: 0,
  gEn: 'super.method() calls the parent\'s version of an overridden method on the same object. (B) calls Book.toString() again — infinite recursion, StackOverflowError. (C) treats an instance method as static: compile error. (D) is not valid syntax.',
  gVi: 'super.method() gọi phiên bản của lớp cha cho phương thức đã bị ghi đè, trên cùng đối tượng. (B) gọi lại Book.toString() — đệ quy vô hạn, StackOverflowError. (C) coi phương thức đối tượng như static: lỗi biên dịch. (D) sai cú pháp.' });
q({ ch: 4, ma: 'Q24', en: 'What is the result of compiling and running this code?', vi: 'Biên dịch và chạy đoạn code này thì kết quả là gì?', o: [CE, ['14'], ['0'], ['An IllegalAccessError at run time', 'IllegalAccessError lúc chạy']], d: 0,
  gEn: `An overriding method may not be LESS accessible than the method it overrides: public in Item, package-private in Book. javac: "${(RA.Q24.ra.replace(/^.*?error: /, ''))}" (… attempting to assign weaker access privileges; was public). Otherwise code holding an Item reference could call a method the Book hides.`,
  gVi: `Phương thức ghi đè không được truy cập HẸP hơn phương thức bị ghi đè: Item để public, Book để mức package. javac báo: "${(RA.Q24.ra.replace(/^.*?error: /, ''))}" (… attempting to assign weaker access privileges; was public). Nếu không, code cầm tham chiếu Item sẽ gọi được một phương thức mà Book giấu đi.` });

/* ═════════ Chương 5 ═════════ */
q({ ch: 5, ma: 'Q25', en: 'What is the result of compiling and running this code?', vi: 'Biên dịch và chạy đoạn code này thì kết quả là gì?', o: [CE, ['0'], ['An AbstractMethodError at run time', 'AbstractMethodError lúc chạy'], ['null']], d: 0,
  gEn: `An abstract class can never be instantiated, even if it had no abstract method: "${(RA.Q25.ra.replace(/^.*?error: /, ''))}". It exists to be EXTENDED (Book, Magazine, Dvd) and to hold the shared part. Variables of type LibraryItem are fine — they point at subclass objects.`,
  gVi: `Lớp trừu tượng không bao giờ tạo được đối tượng, kể cả khi không có phương thức trừu tượng nào: "${(RA.Q25.ra.replace(/^.*?error: /, ''))}". Nó sinh ra để được KẾ THỪA (Book, Magazine, Dvd) và giữ phần chung. Biến kiểu LibraryItem thì vẫn dùng được — nó trỏ tới đối tượng của lớp con.` });
q({ ch: 5, ma: 'Q26', en: 'What is the result of compiling and running this code?', vi: 'Biên dịch và chạy đoạn code này thì kết quả là gì?', o: [CE, ['1'], ['50000'], ['An IllegalAccessError at run time', 'IllegalAccessError lúc chạy']], d: 0,
  gEn: `Every field of an interface is implicitly public static final — a constant. Assigning to it does not compile: JDK 21 says "${(RA.Q26.ra.replace(/^.*?error: /, ''))}", JDK 8 "${(RA.Q26.jdk8.replace(/^.*?error: /, ''))}". Interfaces describe behaviour; data with rules belongs in classes (or in Constants).`,
  gVi: `Mọi trường của interface ngầm là public static final — một hằng. Gán vào nó thì không biên dịch được: JDK 21 báo "${(RA.Q26.ra.replace(/^.*?error: /, ''))}", JDK 8 báo "${(RA.Q26.jdk8.replace(/^.*?error: /, ''))}". Interface mô tả hành vi; dữ liệu có luật thuộc về lớp (hoặc Constants).` });
q({ ch: 5, ma: 'Q27', en: 'What is printed (Java 8 or later)?', vi: 'Chương trình in ra gì (Java 8 trở lên)?', o: [['Hi'], ['Compilation error: Desk must implement hi()', 'Lỗi biên dịch: Desk phải cài hi()'], ['null'], ['An AbstractMethodError at run time', 'AbstractMethodError lúc chạy']], d: 0,
  gEn: 'Since Java 8 an interface may have default methods with a body. A class that implements the interface inherits that body unless it overrides it, so Desk compiles without writing hi(). Default methods let an interface grow without breaking every class that implements it.',
  gVi: 'Từ Java 8, interface được có phương thức default kèm thân. Lớp cài interface thừa hưởng thân đó nếu không tự ghi đè, nên Desk biên dịch được mà không viết hi(). Phương thức default giúp interface lớn thêm mà không làm hỏng mọi lớp đang cài nó.' });
q({ ch: 5, ma: 'Q28', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['3000 0'], ['5000 1000'], ['3000 -1000'], ['Compilation error: an interface cannot be instantiated', 'Lỗi biên dịch: không tạo được đối tượng từ interface']], d: 0,
  gEn: 'new IFeePolicy() { ... } does not instantiate the interface: it declares an ANONYMOUS class that implements it and creates one object of that class. The body is the Staff rule of CT Library: the first 2 late days are free, Math.max(0, …) keeps the fee from going negative: (5−2)×1000 = 3000, and 1 day ⇒ 0.',
  gVi: 'new IFeePolicy() { ... } không tạo đối tượng từ interface: nó khai một lớp ẨN DANH cài interface đó rồi tạo một đối tượng của lớp ấy. Thân hàm là luật cán bộ của CT Library: 2 ngày trễ đầu miễn phí, Math.max(0, …) giữ phí không âm: (5−2)×1000 = 3000, và 1 ngày ⇒ 0.' });
q({ ch: 5, en: 'Which statement about abstract classes and interfaces (Java 8) is TRUE?', vi: 'Phát biểu nào về lớp trừu tượng và interface (Java 8) là ĐÚNG?', o: [['A class can implement several interfaces but extend only one class', 'Một lớp cài được nhiều interface nhưng chỉ kế thừa được một lớp'], ['An interface can have instance fields that each object keeps', 'Interface có trường riêng cho từng đối tượng'], ['An abstract class cannot have a constructor', 'Lớp trừu tượng không được có constructor'], ['Every method of an abstract class must be abstract', 'Mọi phương thức của lớp trừu tượng phải trừu tượng']], d: 0,
  gEn: 'class Book extends LibraryItem implements Borrowable, Searchable is legal; two extends is not. Interface fields are constants, not per-object state (B). Abstract classes DO have constructors, called by subclasses through super(...) (C). An abstract class may mix abstract and ordinary methods — LibraryItem has getTitle() with a body (D).',
  gVi: 'class Book extends LibraryItem implements Borrowable, Searchable là hợp lệ; hai lần extends thì không. Trường của interface là hằng, không phải trạng thái riêng từng đối tượng (B). Lớp trừu tượng CÓ constructor, lớp con gọi qua super(...) (C). Lớp trừu tượng được trộn phương thức trừu tượng với phương thức thường — LibraryItem có getTitle() kèm thân (D).' });
q({ ch: 5, en: 'LoanService keeps <code>HashMap&lt;Integer, IFeePolicy&gt;</code> (member type → fee policy). The club adds a new member type "Guest" with its own fee rule. What is the cleanest change?', vi: 'LoanService giữ <code>HashMap&lt;Integer, IFeePolicy&gt;</code> (loại thẻ → chính sách phí). CLB thêm loại thẻ mới "Khách" với luật phí riêng. Cách sửa gọn nhất là gì?', o: [['Write a GuestFeePolicy class implementing IFeePolicy and put it into the map — no existing formula changes', 'Viết lớp GuestFeePolicy cài IFeePolicy rồi put vào map — không sửa công thức nào đang có'], ['Add an if (type == GUEST) branch inside StudentFeePolicy', 'Thêm nhánh if (type == GUEST) vào StudentFeePolicy'], ['Add a switch on the member type in every method that computes a fee', 'Thêm switch theo loại thẻ vào mọi hàm tính phí'], ['Copy LoanService into GuestLoanService', 'Chép LoanService thành GuestLoanService']], d: 0,
  gEn: 'This is the Strategy pattern and the Open/Closed principle: the code is OPEN for a new behaviour (a new class) and CLOSED for modification (no tested formula is touched). (B) and (C) spread the type check everywhere; (D) duplicates the whole service so every later fix must be made twice.',
  gVi: 'Đây là mẫu Strategy và nguyên lý Mở/Đóng: code MỞ cho hành vi mới (một lớp mới) và ĐÓNG với việc sửa (không đụng công thức đã kiểm thử nào). (B) và (C) rải phép kiểm loại thẻ khắp nơi; (D) nhân đôi cả service, mọi lần sửa sau phải làm hai lần.' });

/* ═════════ Chương 6 ═════════ */
q({ ch: 6, ma: 'Q31', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['try finally 1'], ['try 1'], ['try 1 finally'], ['finally try 1']], d: 0,
  gEn: 'return 1 evaluates the value, then — before the method actually leaves — the finally block runs and prints "finally ". Only then does main receive 1 and print it. finally runs on every exit path (normal end, return, exception), which is why it is the place for clean-up.',
  gVi: 'return 1 tính xong giá trị, rồi — trước khi phương thức thật sự rời đi — khối finally chạy và in "finally ". Sau đó main mới nhận 1 và in ra. finally chạy trên MỌI đường ra (chạy hết, return, ngoại lệ), vì thế nó là chỗ để dọn dẹp.' });
q({ ch: 6, ma: 'Q32', en: 'What is the result of compiling and running this code?', vi: 'Biên dịch và chạy đoạn code này thì kết quả là gì?', o: [CE, ['E'], ['IO'], ['Nothing is printed', 'Không in gì']], d: 0,
  gEn: `catch blocks are tried top to bottom, so a subclass must come BEFORE its superclass. IOException is a subclass of Exception: after catch (Exception e) its block is unreachable, and javac refuses: "${(RA.Q32.ra.replace(/^.*?error: /, ''))}". Put catch (IOException e) first.`,
  gVi: `Các khối catch được thử từ trên xuống, nên lớp con phải đứng TRƯỚC lớp cha. IOException là lớp con của Exception: sau catch (Exception e) thì khối của nó không bao giờ tới được, và javac từ chối: "${(RA.Q32.ra.replace(/^.*?error: /, ''))}". Đặt catch (IOException e) lên trước.` });
q({ ch: 6, en: 'Which exception is CHECKED (the compiler forces you to catch it or declare it with throws)?', vi: 'Ngoại lệ nào là CHECKED (trình biên dịch buộc phải bắt hoặc khai throws)?', o: [['java.io.IOException'], ['java.lang.NullPointerException'], ['java.lang.ArithmeticException'], ['java.lang.ArrayIndexOutOfBoundsException']], d: 0,
  gEn: 'Checked exceptions extend Exception but not RuntimeException: they are outcomes a correct program must still expect (a file that cannot be read). The other three extend RuntimeException — unchecked — and usually signal a bug to fix, not a case to handle. CT Library\'s LibraryException is checked on purpose: "the card is locked" is a normal outcome the controller must handle.',
  gVi: 'Ngoại lệ checked kế thừa Exception nhưng không kế thừa RuntimeException: đó là kết cục mà chương trình đúng vẫn phải lường trước (một tệp không đọc được). Ba cái còn lại kế thừa RuntimeException — unchecked — thường báo một lỗi lập trình cần sửa, không phải tình huống cần xử lý. LibraryException của CT Library cố ý là checked: "thẻ bị khoá" là kết cục bình thường mà controller phải xử lý.' });
q({ ch: 6, ma: 'Q34', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['ok limit 3 end'], ['ok limit 3 ok end'], ['ok end'], ['limit 3 end']], d: 0,
  gEn: 'borrow(1, 3) is fine: "ok ". borrow(3, 3) throws — the rest of the try block, including borrow(0, 3), is SKIPPED and control jumps to the catch, which prints the message "limit 3". After the catch the program continues normally: " end". This is why a controller puts all steps of one operation in one try: a refused step stops the later ones.',
  gVi: 'borrow(1, 3) ổn: "ok ". borrow(3, 3) ném — phần còn lại của khối try, kể cả borrow(0, 3), bị BỎ QUA và điều khiển nhảy tới catch, in thông điệp "limit 3". Sau catch chương trình chạy tiếp bình thường: " end". Vì thế controller đặt mọi bước của một thao tác trong một khối try: bước bị từ chối thì các bước sau không chạy.' });
q({ ch: 6, ma: 'Q35', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['Infinity AE'], ['AE'], ['Infinity Infinity'], ['NaN AE']], d: 0,
  gEn: 'Floating-point division follows IEEE 754: 5.0 / 0 is Infinity, no exception. Integer division by zero has no such value and throws ArithmeticException ("/ by zero"), caught and printed as "AE". NaN would come from 0.0 / 0.',
  gVi: 'Chia số thực theo chuẩn IEEE 754: 5.0 / 0 ra Infinity, không có ngoại lệ. Chia số nguyên cho 0 không có giá trị như vậy nên ném ArithmeticException ("/ by zero"), bị bắt và in "AE". NaN là kết quả của 0.0 / 0.' });
q({ ch: 6, en: 'In <code>interface IBookRepository { void save() throws StorageException; }</code> where StorageException is checked, which implementation of <code>save()</code> does NOT compile?', vi: 'Với <code>interface IBookRepository { void save() throws StorageException; }</code> trong đó StorageException là checked, bản cài <code>save()</code> nào KHÔNG biên dịch được?', o: [['public void save() throws Exception { ... }'], ['public void save() { ... }'], ['public void save() throws StorageException { ... }'], ['public void save() throws IllegalStateException { ... }']], d: 0,
  gEn: 'An implementation (or override) may throw the same checked exceptions, fewer, or narrower ones — never broader or new ones: callers that only know the interface prepared for StorageException, not for every Exception. (B) throws nothing: allowed (that is how InMemoryBookRepository works). (D) adds an unchecked exception: always allowed.',
  gVi: 'Bản cài (hay bản ghi đè) được ném cùng ngoại lệ checked, ít hơn, hoặc hẹp hơn — không bao giờ rộng hơn hay thêm mới: nơi gọi chỉ biết interface đã chuẩn bị cho StorageException, không chuẩn bị cho mọi Exception. (B) không ném gì: được (InMemoryBookRepository làm đúng vậy). (D) thêm ngoại lệ unchecked: luôn được.' });

/* ═════════ Chương 7 ═════════ */
q({ ch: 7, ma: 'Q37', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['null 0 3'], ['0 0 3'], ['A NullPointerException is thrown', 'Ném NullPointerException'], ['null null 3']], d: 0,
  gEn: 'new Book[3] creates an array of 3 REFERENCES, all null — no Book object exists yet; each slot needs its own new Book(...). A new int[] is filled with 0. Printing a null reference with + gives "null" (no exception: nothing is called on it). length is the capacity, 3.',
  gVi: 'new Book[3] tạo mảng 3 THAM CHIẾU, tất cả là null — chưa có đối tượng Book nào; mỗi ô cần new Book(...) riêng. int[] mới được lấp 0. Nối một tham chiếu null bằng + ra chữ "null" (không ngoại lệ: không gọi gì trên nó). length là sức chứa, 3.' });
q({ ch: 7, ma: 'Q38', en: 'The code removes the element at index k from a partly filled array. What is printed?', vi: 'Đoạn code xoá phần tử ở vị trí k khỏi một mảng dùng một phần. Chương trình in ra gì?', o: [['B1 B3 B4 B4'], ['B1 B3 B4 null'], ['B1 B2 B4 B4'], ['B1 B4 B4 B4']], d: 0,
  gEn: 'Shifting left from k overwrites B2 with B3, then B3 with B4: the logical list (size 3) is B1 B3 B4. The array itself still has 4 slots and the last one still holds the OLD B4 — removing by shifting does not clear the tail. Lab 7 sets that slot to null so the removed object can be garbage-collected.',
  gVi: 'Dời trái từ k ghi đè B2 bằng B3, rồi B3 bằng B4: danh sách logic (size 3) là B1 B3 B4. Bản thân mảng vẫn có 4 ô và ô cuối vẫn giữ B4 CŨ — xoá bằng cách dời không tự xoá đuôi. Lab 7 gán ô đó bằng null để đối tượng đã xoá được gom rác.' });
q({ ch: 7, ma: 'Q39', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['[Basic, Clean, algo, java]'], ['[algo, Basic, Clean, java]'], ['[java, Clean, algo, Basic]'], ['[algo, java, Basic, Clean]']], d: 0,
  gEn: 'Arrays.sort on String uses compareTo — Unicode order, where every upper-case letter (A–Z, 65–90) comes before every lower-case letter (a–z, 97–122). So "Basic" and "Clean" come first. For the dictionary order of (B), sort with String.CASE_INSENSITIVE_ORDER, as BookService does for titles.',
  gVi: 'Arrays.sort trên String dùng compareTo — thứ tự Unicode, trong đó mọi chữ hoa (A–Z, 65–90) đứng trước mọi chữ thường (a–z, 97–122). Nên "Basic" và "Clean" đứng đầu. Muốn thứ tự từ điển như (B) thì sắp với String.CASE_INSENSITIVE_ORDER, như BookService sắp tên sách.' });
q({ ch: 7, ma: 'Q40', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['3 2 null'], ['3 2 0'], ['3 0 null'], ['A NullPointerException is thrown', 'Ném NullPointerException']], d: 0,
  gEn: 'new int[3][] makes an array of 3 references to int arrays ("rows"), all null. Only row 0 is created, with 2 elements. Printing m[1] prints the null reference; m[1].length (not asked) would throw NullPointerException. Rows of a 2-D array may have different lengths (a jagged array).',
  gVi: 'new int[3][] tạo mảng 3 tham chiếu tới mảng int ("hàng"), tất cả null. Chỉ hàng 0 được tạo, gồm 2 phần tử. In m[1] là in tham chiếu null; còn m[1].length (đề không hỏi) mới ném NullPointerException. Các hàng của mảng 2 chiều có thể dài ngắn khác nhau (mảng răng cưa).' });

/* ═════════ Chương 8 ═════════ */
q({ ch: 8, ma: 'Q41', en: 'Member does not override equals() and hashCode(). What is printed?', vi: 'Member không ghi đè equals() và hashCode(). Chương trình in ra gì?', o: [['2'], ['1'], ['0'], ['Compilation error', 'Lỗi biên dịch']], d: 0,
  gEn: 'HashSet decides "same element?" with hashCode() then equals(). Without overrides both come from Object and compare IDENTITY: two new Member("M1") are two different objects, so both are kept. Override equals AND hashCode on the same field (id), as Lab 8 does, to get 1.',
  gVi: 'HashSet quyết định "cùng phần tử?" bằng hashCode() rồi equals(). Không ghi đè thì cả hai lấy từ Object và so DANH TÍNH: hai new Member("M1") là hai đối tượng khác nhau, nên giữ cả hai. Ghi đè equals VÀ hashCode trên cùng một trường (id), như Lab 8, thì mới ra 1.' });
q({ ch: 8, ma: 'Q42', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['{B1=2, B2=3, D9=1}'], ['{B2=3, B1=2, D9=1}'], ['{B1=1, B2=1, D9=1}'], ['{B2=1, B1=1, B2=1, D9=1, B1=1, B2=1}']], d: 0,
  gEn: 'getOrDefault(id, 0) + 1 is the counting idiom: missing key ⇒ start from 0. A Map keeps ONE value per key, so put() overwrites the count. TreeMap keeps keys sorted (B1 < B2 < D9), whatever the insertion order — (B) would be insertion order (LinkedHashMap).',
  gVi: 'getOrDefault(id, 0) + 1 là mẫu đếm: chưa có khoá ⇒ bắt đầu từ 0. Map giữ MỘT giá trị cho mỗi khoá, nên put() ghi đè số đếm. TreeMap giữ khoá theo thứ tự sắp (B1 < B2 < D9), bất kể thứ tự thêm — (B) là thứ tự thêm vào (LinkedHashMap).' });
q({ ch: 8, ma: 'Q43', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['[M1, M3]'], ['CME'], ['[M1, M2, M3]'], ['Compilation error', 'Lỗi biên dịch']], d: 0,
  gEn: 'Surprise: no ConcurrentModificationException here. M2 is the SECOND-TO-LAST element: after remove(x) the size drops to 2 and the iterator\'s cursor is already 2, so hasNext() returns false and the loop ends before next() can check for modification. Remove M1 instead and you DO get CME. Never rely on this — use Iterator.remove() or removeIf(); the PE grader\'s hidden tests will hit the case that crashes.',
  gVi: 'Bất ngờ: ở đây KHÔNG có ConcurrentModificationException. M2 là phần tử ÁP CHÓT: sau remove(x) kích thước còn 2 mà con trỏ của iterator đã là 2, nên hasNext() trả false và vòng lặp kết thúc trước khi next() kịp kiểm tra thay đổi. Đổi sang xoá M1 là CÓ CME ngay. Đừng bao giờ dựa vào chuyện này — dùng Iterator.remove() hoặc removeIf(); test ẩn của máy chấm PE sẽ trúng đúng ca làm sập.' });
q({ ch: 8, ma: 'Q44', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['[30]'], ['[20]'], ['[10, 30]'], ['An IndexOutOfBoundsException is thrown', 'Ném IndexOutOfBoundsException']], d: 0,
  gEn: 'ArrayList<Integer> has two remove methods. remove(1) with an int literal picks remove(int index): it removes the element AT index 1 (20) ⇒ [10, 30]. remove(Integer.valueOf(10)) picks remove(Object): it removes the element EQUAL to 10 ⇒ [30].',
  gVi: 'ArrayList<Integer> có hai hàm remove. remove(1) với literal int chọn remove(int index): xoá phần tử Ở vị trí 1 (20) ⇒ [10, 30]. remove(Integer.valueOf(10)) chọn remove(Object): xoá phần tử BẰNG 10 ⇒ [30].' });
q({ ch: 8, en: 'CT Library needs to find a member by id in constant time AND print members in the order they were loaded from members.csv. Which collection fits best?', vi: 'CT Library cần tìm thành viên theo mã trong thời gian hằng số VÀ in thành viên theo đúng thứ tự nạp từ members.csv. Collection nào hợp nhất?', o: [['LinkedHashMap<String, Member>'], ['ArrayList<Member>'], ['TreeMap<String, Member>'], ['HashSet<Member>']], d: 0,
  gEn: 'LinkedHashMap is a HashMap (get by key in O(1)) that also remembers insertion order when you iterate. ArrayList keeps the order but finding by id is a loop, O(n). TreeMap orders by key (O(log n)), not by loading order. A HashSet cannot look up by id at all.',
  gVi: 'LinkedHashMap là một HashMap (lấy theo khoá O(1)) còn nhớ thêm thứ tự thêm vào khi duyệt. ArrayList giữ thứ tự nhưng tìm theo mã là một vòng lặp, O(n). TreeMap sắp theo khoá (O(log n)), không theo thứ tự nạp. HashSet không tra theo mã được.' });
q({ ch: 8, ma: 'Q46', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['[B1, B10, B2]'], ['[B1, B2, B10]'], ['[B10, B1, B2]'], ['[B2, B10, B1]']], d: 0,
  gEn: 'Strings compare character by character: "B1" vs "B10" — "B1" is a prefix, so it is smaller; "B10" vs "B2" — the second characters are \'1\' < \'2\', so "B10" comes before "B2". Numbers inside text do not sort as numbers — the reason CT Library pads ids to a fixed width (B001, B002, B010).',
  gVi: 'Chuỗi so từng ký tự: "B1" với "B10" — "B1" là tiền tố nên nhỏ hơn; "B10" với "B2" — ký tự thứ hai \'1\' < \'2\', nên "B10" đứng trước "B2". Số nằm trong chữ không sắp như số — lý do CT Library đệm mã đủ độ rộng (B001, B002, B010).' });

/* ═════════ Chương 9 ═════════ */
q({ ch: 9, en: 'Which line opens <code>data/books.csv</code> for reading LINE BY LINE in UTF-8 on every machine (Windows included)?', vi: 'Dòng nào mở <code>data/books.csv</code> để đọc TỪNG DÒNG bằng UTF-8 trên mọi máy (kể cả Windows)?', o: [['new BufferedReader(new InputStreamReader(new FileInputStream(f), StandardCharsets.UTF_8))'], ['new BufferedReader(new FileReader(f)) — FileReader picks the charset by itself', 'new BufferedReader(new FileReader(f)) — FileReader tự chọn bảng mã'], ['new FileInputStream(f), then read() one byte at a time until it returns -1', 'new FileInputStream(f), rồi read() từng byte tới khi trả -1'], ['new ObjectInputStream(new BufferedInputStream(new FileInputStream(f)))']], d: 0,
  gEn: 'InputStreamReader turns bytes into characters with the charset you NAME; BufferedReader adds readLine(). (B) uses the machine\'s default charset on Java 8 — Windows-1252 on many Vietnamese Windows machines, so "Mắt Biếc" turns into garbage. (C) reads raw bytes, no lines. (D) reads serialized objects, not text.',
  gVi: 'InputStreamReader đổi byte thành ký tự bằng bảng mã bạn GỌI TÊN; BufferedReader thêm readLine(). (B) dùng bảng mã mặc định của máy trên Java 8 — Windows-1252 trên nhiều máy Windows tiếng Việt, nên "Mắt Biếc" thành chữ rác. (C) đọc byte thô, không có dòng. (D) đọc đối tượng tuần tự hoá, không phải văn bản.' });
q({ ch: 9, ma: 'Q48', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['2 4'], ['4 4'], ['2 2'], ['3 4']], d: 0,
  gEn: 'split(",") with the default limit REMOVES trailing empty strings: "M1,An,," gives [M1, An]. split(",", -1) keeps them: [M1, An, "", ""]. A CSV loader that counts columns must use -1, or a member with empty last columns looks like a broken line.',
  gVi: 'split(",") với giới hạn mặc định BỎ các chuỗi rỗng ở cuối: "M1,An,," cho [M1, An]. split(",", -1) giữ lại: [M1, An, "", ""]. Bộ nạp CSV có đếm số cột phải dùng -1, không thì thành viên có cột cuối trống bị coi là dòng hỏng.' });
q({ ch: 9, ma: 'Q49', en: 'What is printed?', vi: 'Chương trình in ra gì?', o: [['open A open B body close B close A'], ['open A open B body close A close B'], ['open A open B body'], ['open A body close A open B close B']], d: 0,
  gEn: 'try-with-resources opens the resources in the order written and closes them automatically in REVERSE order (like a stack), after the body, even if the body throws. Reverse order matters: the writer B may wrap the stream A, so B must be flushed and closed before A.',
  gVi: 'try-with-resources mở tài nguyên theo thứ tự viết và tự đóng theo thứ tự NGƯỢC LẠI (như ngăn xếp), sau thân khối, kể cả khi thân ném ngoại lệ. Thứ tự ngược là quan trọng: writer B có thể bọc luồng A, nên B phải được đẩy hết và đóng trước A.' });
q({ ch: 9, en: '<code>PrintWriter</code> methods never throw <code>IOException</code>. After writing all lines of books.csv, how does FileBookRepository find out that the disk was full?', vi: 'Các phương thức của <code>PrintWriter</code> không bao giờ ném <code>IOException</code>. Ghi xong mọi dòng của books.csv, FileBookRepository biết đĩa đầy bằng cách nào?', o: [['Call writer.checkError(), which flushes and returns true if any error happened', 'Gọi writer.checkError(): nó đẩy dữ liệu và trả true nếu đã có lỗi'], ['Catch IOException around println', 'Bắt IOException quanh println'], ['Check that println returned false', 'Kiểm println có trả false không'], ['It cannot know; PrintWriter must not be used', 'Không biết được; không được dùng PrintWriter']], d: 0,
  gEn: 'PrintWriter swallows I/O errors and only sets an internal flag; checkError() flushes and reports it. A catch (IOException) around println does not even compile (println does not declare it), and println returns void. CT Library turns a true checkError() into a StorageException, so the menu reports the failure instead of pretending it saved.',
  gVi: 'PrintWriter nuốt lỗi I/O và chỉ bật một cờ bên trong; checkError() đẩy dữ liệu và báo cờ đó. catch (IOException) quanh println còn không biên dịch được (println không khai ngoại lệ đó), và println trả void. CT Library đổi checkError() = true thành StorageException, để menu báo lỗi thay vì giả vờ đã lưu.' });

